def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_each_transcript_equally():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": None}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_window_boundaries():
    counts = [2, 0, 1, 3]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 4
    assert flags_in_window(counts, 5) == 6


def test_rates_and_rankings_with_empty_groups_and_ties():
    groups = {"z": [{"flagged": True}], "empty": [], "b": [{"flagged": False}], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0)]
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_longest_streak_resets_on_nonpositive_days():
    assert longest_flag_streak([1, -1, 2, 1, 0, 1]) == 2
    assert longest_flag_streak([]) == 0


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"g": parse_transcript_log(["a,2,1", "b,4,0", "c,5,"]), "empty": []}
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
