@pytest.mark.parametrize("bad_line", ["missing,1", "extra,1,0,field", "x,bad,1"])
def test_parse_error_counts_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log([" # comment", "ok,2,0", "", bad_line])


def test_dedupe_keeps_last_occurrence_then_sorts_by_day_and_id():
    events = parse_transcript_log(["x,5,1", "z,1,1", "a,2,0", "x,2,0"])
    assert dedupe_transcripts(events) == [events[1], events[2], events[3]]


def test_daily_counts_include_gaps_and_ignore_outside_days():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,4,", "e,5,1"])
    assert daily_flag_counts(events, 2, 4) == [2, 0, 0]
